  'wizard.opamp.kind': ['Kiểu tầng', 'Stage'],
  'wizard.opamp.kind.inverting': ['Khuếch đại đảo', 'Inverting amplifier'],
  'wizard.opamp.kind.noninverting': ['Khuếch đại không đảo', 'Non-inverting amplifier'],
